import csv
import io
import re


def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = []
    while True:
        try:
            record = next(reader)
        except StopIteration:
            break
        except csv.Error:
            continue
        records.append([value if isinstance(value, str) else str(value) for value in record])

    header_index = None
    for index, record in enumerate(records):
        if any(value.strip() for value in record):
            header_index = index
            if len(record) > 1:
                break

    if header_index is None:
        return {"columns": [], "rows": []}

    columns = records[header_index][:]
    data_records = records[header_index + 1:]

    width = max([len(columns)] + [len(record) for record in data_records])
    while len(columns) < width:
        columns.append("extra_{}".format(len(columns) - len(records[header_index]) + 1))

    rows = []
    for record in data_records:
        rows.append(record[:width] + [""] * max(0, width - len(record)))

    return {"columns": columns, "rows": rows}
